import React, { useState, useEffect } from 'react';
import { 
  BrainCircuit, LogOut, User, GraduationCap, ArrowRight,
  ShieldCheck, Wallet, Award, Save, Calendar, Search, 
  LayoutDashboard, AlertCircle, Users, FileText,
  TrendingDown, Filter, Download, Plus, Trash2, 
  ChevronRight, Settings, Info, Lock, Mail, X,
  Activity, Home, MapPin, BookOpen, CheckCircle2,
  Megaphone, BellRing, ClipboardCheck, Edit3
} from 'lucide-react';

// --- SHARED MOCK DATA ---
// We start with a few students, but the CSV upload will add more!
const INITIAL_STUDENTS = [
  { id: '1', name: 'Juan Dela Cruz', email: 'juan@univ.edu', income: 8500, absences: 14, risk: 78, status: 'At Risk', studyTime: 8, distance: 15, parentEdu: 1, interventions: [] },
  { id: '2', name: 'Maria Santos', email: 'maria@univ.edu', income: 28000, absences: 2, risk: 12, status: 'Stable', studyTime: 25, distance: 2, parentEdu: 4, interventions: [] },
  { id: '3', name: 'Kevin Lee', email: 'kevin@univ.edu', income: 14500, absences: 6, risk: 32, status: 'Stable', studyTime: 12, distance: 8, parentEdu: 2, interventions: [] },
];

const TEACHER_ACCOUNT = { email: 'teacher@univ.edu', password: '123' };
const ADMIN_ACCOUNT = { email: 'admin@univ.edu', password: '123' };

// --- HELPER COMPONENTS ---
const RiskIndicator = ({ label, value, max, icon: Icon, colorClass }) => (
  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
    <div className="flex justify-between items-center mb-2">
      <div className="flex items-center gap-2">
        <Icon size={16} className="text-slate-400" />
        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{label}</span>
      </div>
      <span className="text-xs font-black text-slate-800">{value}</span>
    </div>
    <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden">
      <div 
        className={`h-full transition-all duration-1000 ${colorClass}`} 
        style={{ width: `${Math.min(100, (parseFloat(String(value).replace(/[^0-9.]/g, '')) / max) * 100)}%` }}
      />
    </div>
  </div>
);

// --- 1. STUDENT PORTAL (Now Dynamic) ---
const StudentPortal = ({ studentData, updateStudent, notifications }) => {
  const [activeTab, setActiveTab] = useState('home');
  const [profile, setProfile] = useState(studentData);

  useEffect(() => { setProfile(studentData); }, [studentData]);

  const currentRisk = profile.risk;
  const successRate = 100 - currentRisk;

  const getRiskStatus = (score) => {
    if (score > 50) return { color: 'text-rose-500', bg: 'bg-rose-50', label: 'High Risk' };
    if (score > 20) return { color: 'text-amber-500', bg: 'bg-amber-50', label: 'Moderate' };
    return { color: 'text-emerald-500', bg: 'bg-emerald-50', label: 'Low Risk' };
  };

  const markInterventionDone = (idx) => {
    const updatedInterventions = [...profile.interventions];
    updatedInterventions.splice(idx, 1);
    const newRisk = Math.max(0, profile.risk - 5); // Gamification: Lower risk on task completion
    updateStudent({ ...profile, risk: newRisk, interventions: updatedInterventions });
    alert("Task Completed! Risk Score Lowered.");
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="lg:col-span-3 space-y-2">
        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 mb-6">
          <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center mb-4">
            <User className="text-indigo-600" size={32} />
          </div>
          <h3 className="font-black text-slate-800 leading-tight">{profile.name}</h3>
          <p className="text-xs font-bold text-slate-400">{profile.email}</p>
        </div>
        
        {notifications.length > 0 && (
          <div className="bg-indigo-600 p-6 rounded-[2rem] text-white shadow-xl shadow-indigo-200 mb-6">
             <div className="flex items-center gap-2 mb-2">
               <Megaphone size={16} className="animate-pulse"/>
               <h4 className="text-xs font-black uppercase tracking-widest">Admin Broadcast</h4>
             </div>
             <p className="text-xs font-bold leading-relaxed opacity-90">{notifications[notifications.length-1].message}</p>
          </div>
        )}
      </div>

      <div className="lg:col-span-9 space-y-6">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-8 items-center relative overflow-hidden">
            <div className="relative w-40 h-40 flex items-center justify-center shrink-0">
                <svg className="w-full h-full transform -rotate-90">
                <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="12" fill="transparent" className="text-slate-100" />
                <circle cx="80" cy="80" r="70" stroke="currentColor" strokeWidth="12" fill="transparent" strokeDasharray={440} strokeDashoffset={440 - (440 * successRate) / 100} className="text-indigo-600 transition-all duration-1000" />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-3xl font-black text-slate-800">{successRate}%</span>
                <span className="text-[10px] font-bold text-slate-400 uppercase">Success Rate</span>
                </div>
            </div>
            <div className="flex-1 space-y-4 relative z-10">
            <h2 className="text-2xl font-black text-slate-800">Welcome, {profile.name.split(' ')[0]}</h2>
            <p className="text-slate-500 text-sm">Status: <span className={`font-bold ${getRiskStatus(currentRisk).color}`}>{getRiskStatus(currentRisk).label}</span></p>
            <div className="flex gap-2">
                <div className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-xs font-bold flex items-center gap-2"><Wallet size={14}/> PHP {profile.income}</div>
                <div className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-xs font-bold flex items-center gap-2"><AlertCircle size={14}/> {profile.absences} Absences</div>
            </div>
            </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-4">
        <h4 className="font-black text-slate-800 flex items-center gap-2 text-lg"><ClipboardCheck className="text-indigo-500"/> My Tasks</h4>
        <div className="space-y-3">
            {profile.interventions.length > 0 ? (
            profile.interventions.map((task, idx) => (
                <div key={idx} className="p-4 bg-indigo-50 rounded-2xl flex justify-between items-center">
                <span className="text-sm font-bold text-indigo-900">{task}</span>
                <button onClick={() => markInterventionDone(idx)} className="p-2 bg-white text-emerald-500 rounded-xl"><CheckCircle2 size={16}/></button>
                </div>
            ))
            ) : <p className="text-slate-400 text-xs font-bold">No pending tasks.</p>}
        </div>
        </div>
      </div>
    </div>
  );
};

// --- 2. TEACHER PORTAL (CSV & Editing) ---
const TeacherPortal = ({ students, setStudents }) => {
  const [selectedStudent, setSelectedStudent] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [editMode, setEditMode] = useState(false); // New: Edit Mode
  const [notification, setNotification] = useState(null);

  // Filter Logic
  const filteredStudents = students.filter(student => 
    student.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    student.email.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // CSV Upload Logic
  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target.result;
        const rows = text.split('\n').filter(r => r.trim()).slice(1); // Skip header
        
        const newStudents = rows.map((row, index) => {
            const cols = row.split(',').map(c => c.trim());
            // Basic CSV parsing: Name, Email, Income, Absences
            if(cols.length < 4) return null;
            const income = parseInt(cols[2]);
            const absences = parseInt(cols[3]);
            // Auto-calculate risk for new students
            const calculatedRisk = Math.min(100, (absences * 5) + (income < 10000 ? 20 : 0));
            
            return {
                id: `csv-${Date.now()}-${index}`,
                name: cols[0],
                email: cols[1],
                income: income,
                absences: absences,
                risk: calculatedRisk,
                status: calculatedRisk > 50 ? 'At Risk' : 'Stable',
                interventions: [],
                studyTime: 10, // Default
                distance: 5    // Default
            };
        }).filter(s => s !== null);

        // Update Global State: Add new students to the list
        setStudents(prev => [...prev, ...newStudents]);
        setNotification(`Successfully added ${newStudents.length} students from CSV.`);
        setIsUploading(false);
    };
    reader.readAsText(file);
  };

  const handleUpdateStudent = (updatedData) => {
      // Logic to recalculate risk if teacher changes data
      const newRisk = Math.min(100, (updatedData.absences * 5) + (updatedData.income < 10000 ? 20 : 0));
      const finalData = { ...updatedData, risk: newRisk, status: newRisk > 50 ? 'At Risk' : 'Stable' };
      
      const newStudentList = students.map(s => s.id === finalData.id ? finalData : s);
      setStudents(newStudentList);
      setSelectedStudent(null);
      setEditMode(false);
      setNotification(`Updated profile for ${finalData.name}`);
  };

  const deployIntervention = (type) => {
      const task = type === 'financial' ? "Apply for TES Subsidy" : "Report to Guidance Office";
      const updated = { ...selectedStudent, interventions: [...selectedStudent.interventions, task] };
      handleUpdateStudent(updated);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Faculty Dashboard</h2>
          <p className="text-slate-400 text-sm font-bold">Manage class data and upload records.</p>
        </div>
        <button onClick={() => setIsUploading(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center gap-2 hover:bg-indigo-700 shadow-xl transition-all">
            <Plus size={16}/> Upload Class CSV
        </button>
      </div>

      {notification && (
        <div className="bg-emerald-500 text-white p-4 rounded-2xl flex items-center justify-between shadow-lg">
          <span className="font-bold text-sm flex items-center gap-2"><CheckCircle2 size={18}/> {notification}</span>
          <button onClick={() => setNotification(null)}><X size={16}/></button>
        </div>
      )}

      {/* CLASS LIST */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
          <h4 className="font-black text-slate-800">Student Registry ({students.length})</h4>
          <input 
            placeholder="Search student..." 
            className="pl-4 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-xs outline-none focus:border-indigo-500" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="max-h-[500px] overflow-y-auto">
          <table className="w-full text-left">
            <thead className="sticky top-0 bg-slate-50 z-10">
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-8 py-4">Student Name</th>
                <th className="px-8 py-4 text-center">Absences</th>
                <th className="px-8 py-4 text-center">Risk Score</th>
                <th className="px-8 py-4 w-24">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-all">
                  <td className="px-8 py-5">
                    <p className="text-sm font-black text-slate-800">{student.name}</p>
                    <p className="text-[10px] text-slate-400 font-bold">{student.email}</p>
                  </td>
                  <td className="px-8 py-5 text-center font-bold text-slate-600">{student.absences}</td>
                  <td className="px-8 py-5 text-center">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black ${student.risk > 50 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                        {student.risk}%
                    </span>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <button onClick={() => setSelectedStudent(student)} className="p-2 bg-slate-100 text-slate-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><Edit3 size={16}/></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* STUDENT DETAIL & EDIT MODAL */}
      {selectedStudent && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[200] flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
              <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xl font-black text-slate-800">{editMode ? 'Edit Profile' : 'Student Analysis'}</h3>
                  <button onClick={() => { setSelectedStudent(null); setEditMode(false); }}><X/></button>
              </div>
              
              {editMode ? (
                  <div className="space-y-4">
                      <div className="space-y-1">
                          <label className="text-[10px] font-black uppercase text-slate-400">Total Absences</label>
                          <input type="number" className="w-full p-3 bg-slate-50 rounded-xl font-bold" value={selectedStudent.absences} onChange={(e) => setSelectedStudent({...selectedStudent, absences: parseInt(e.target.value) || 0})} />
                      </div>
                      <div className="space-y-1">
                          <label className="text-[10px] font-black uppercase text-slate-400">Monthly Income</label>
                          <input type="number" className="w-full p-3 bg-slate-50 rounded-xl font-bold" value={selectedStudent.income} onChange={(e) => setSelectedStudent({...selectedStudent, income: parseInt(e.target.value) || 0})} />
                      </div>
                      <button onClick={() => handleUpdateStudent(selectedStudent)} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black uppercase tracking-widest text-xs mt-4">Save Changes</button>
                  </div>
              ) : (
                  <div className="space-y-6">
                      <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl">
                          <div className="w-12 h-12 bg-indigo-600 text-white rounded-xl flex items-center justify-center font-black text-lg">{selectedStudent.name[0]}</div>
                          <div>
                              <p className="font-black text-slate-800">{selectedStudent.name}</p>
                              <p className="text-xs text-slate-500">{selectedStudent.email}</p>
                          </div>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                           <button onClick={() => deployIntervention('financial')} className="p-4 border border-slate-100 rounded-2xl hover:bg-emerald-50 hover:border-emerald-200 transition-all text-left">
                               <Award className="text-emerald-500 mb-2"/>
                               <p className="text-xs font-black text-slate-800">Grant Subsidy</p>
                           </button>
                           <button onClick={() => setEditMode(true)} className="p-4 border border-slate-100 rounded-2xl hover:bg-indigo-50 hover:border-indigo-200 transition-all text-left">
                               <Edit3 className="text-indigo-500 mb-2"/>
                               <p className="text-xs font-black text-slate-800">Edit Data</p>
                           </button>
                      </div>
                  </div>
              )}
           </div>
        </div>
      )}

      {/* CSV UPLOAD MODAL */}
      {isUploading && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-8 space-y-6 shadow-2xl animate-in zoom-in-95 duration-200 text-center">
            <FileText className="w-16 h-16 text-indigo-600 mx-auto bg-indigo-50 p-4 rounded-2xl"/>
            <div>
                <h3 className="text-2xl font-black text-slate-800">Upload CSV</h3>
                <p className="text-xs text-slate-400 mt-2">Format: Name, Email, Income, Absences</p>
            </div>
            <input type="file" accept=".csv" onChange={handleFileUpload} className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100"/>
            <button onClick={() => setIsUploading(false)} className="text-slate-400 text-xs font-bold uppercase hover:text-rose-500">Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
};

// --- 3. ADMIN PORTAL ---
const AdminPortal = ({ broadcastAlert }) => {
    const [msg, setMsg] = useState("");
    return (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <h2 className="text-3xl font-black text-slate-800 mb-8">Admin Console</h2>
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
                <h4 className="font-black text-slate-800 mb-4">System Broadcast</h4>
                <textarea className="w-full p-4 bg-slate-50 rounded-2xl text-sm mb-4 outline-none focus:border-indigo-500 border border-transparent transition-all" rows="3" placeholder="Enter urgent message..." value={msg} onChange={e => setMsg(e.target.value)}></textarea>
                <button onClick={() => { broadcastAlert(msg); setMsg(""); alert("Sent!"); }} className="bg-rose-500 text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-lg shadow-rose-200">Broadcast Alert</button>
            </div>
        </div>
    );
};

// --- MAIN CONTROLLER ---
export default function App() {
  const [view, setView] = useState('landing'); 
  const [role, setRole] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loginEmail, setLoginEmail] = useState(''); // New: Email Input State
  
  // GLOBAL STATE
  const [students, setStudents] = useState(INITIAL_STUDENTS);
  const [notifications, setNotifications] = useState([]);
  const [currentUserData, setCurrentUserData] = useState(null);

  const updateStudent = (updatedProfile) => {
    setStudents(students.map(s => s.id === updatedProfile.id ? updatedProfile : s));
    if (currentUserData && currentUserData.id === updatedProfile.id) setCurrentUserData(updatedProfile);
  };

  const submitLogin = (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    setTimeout(() => {
      // 1. STUDENT LOGIN
      if(role === 'student') {
          const foundStudent = students.find(s => s.email.toLowerCase() === loginEmail.toLowerCase());
          if(foundStudent) {
              setCurrentUserData(foundStudent);
              setView('dashboard');
          } else {
              alert("Email not found! (Try: juan@univ.edu)");
          }
      } 
      // 2. TEACHER LOGIN
      else if (role === 'teacher') {
          setView('dashboard'); // Simplified for demo
      }
      // 3. ADMIN LOGIN
      else if (role === 'admin') {
          setView('dashboard');
      }
      setIsLoading(false);
    }, 800);
  };

  // --- VIEWS ---
  if (view === 'landing') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white relative overflow-hidden">
        <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-indigo-600/20 blur-[150px] rounded-full"></div>
        <div className="relative z-10 w-full max-w-lg text-center animate-in zoom-in-95 duration-700">
          <div className="inline-flex p-4 rounded-[2.5rem] bg-indigo-500/10 border border-indigo-500/20 mb-8"><BrainCircuit className="text-indigo-400 w-12 h-12" /></div>
          <h1 className="text-6xl font-black mb-4 tracking-tighter italic">Success<span className="text-indigo-500">Predict</span></h1>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.4em] mb-12">AI Student Intervention System</p>
          <div className="space-y-3">
            {['student', 'teacher', 'admin'].map(id => (
              <button key={id} onClick={() => { setRole(id); setView('login'); setLoginEmail(''); }} className="w-full bg-slate-900/50 border border-slate-800 p-5 rounded-[1.5rem] flex items-center justify-between hover:bg-indigo-600 transition-all group">
                <span className="font-black text-sm uppercase tracking-widest pl-2">{id} Access</span>
                <ArrowRight className="group-hover:translate-x-1 transition-transform"/>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (view === 'login') {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="w-full max-w-md bg-[#0f172a] p-10 rounded-[3rem] border border-slate-800 animate-in slide-in-from-bottom-8">
           <button onClick={() => setView('landing')} className="text-slate-500 text-xs font-bold uppercase mb-6 flex items-center gap-2 hover:text-white"><ArrowRight className="rotate-180" size={14}/> Back</button>
           <h2 className="text-2xl font-black uppercase mb-1">{role} Portal</h2>
           <p className="text-slate-500 text-xs mb-8">Please authenticate to continue.</p>
           <form onSubmit={submitLogin} className="space-y-4">
               <div>
                   <label className="text-[10px] font-black text-slate-600 uppercase ml-2">Email Address</label>
                   <input required className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl text-white outline-none focus:border-indigo-500 font-bold" 
                          placeholder={role === 'student' ? 'juan@univ.edu' : 'admin@univ.edu'}
                          value={loginEmail}
                          onChange={e => setLoginEmail(e.target.value)}
                   />
               </div>
               <div>
                   <label className="text-[10px] font-black text-slate-600 uppercase ml-2">Password</label>
                   <input type="password" required defaultValue="123" className="w-full p-4 bg-slate-900 border border-slate-800 rounded-2xl text-white outline-none focus:border-indigo-500 font-bold"/>
               </div>
               <button type="submit" className="w-full py-4 bg-indigo-600 rounded-2xl font-black uppercase text-xs hover:bg-indigo-500 transition-all mt-4">
                   {isLoading ? 'Verifying...' : 'Login Securely'}
               </button>
           </form>
           {role === 'student' && <p className="text-center text-[10px] text-slate-600 mt-6">Try: juan@univ.edu, maria@univ.edu, or any email from your uploaded CSV.</p>}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans">
      <nav className="bg-white/80 backdrop-blur-xl border-b sticky top-0 z-[80] px-8 py-4 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-2 font-black text-xl tracking-tighter italic"><BrainCircuit className="text-indigo-600"/> SUCCESS<span className="text-indigo-600">PREDICT</span></div>
        <button onClick={() => setView('landing')} className="text-rose-500 hover:bg-rose-50 p-2 rounded-xl transition-all"><LogOut size={20}/></button>
      </nav>
      <main className="max-w-7xl mx-auto p-6 lg:p-12">
        {role === 'student' && <StudentPortal studentData={currentUserData} updateStudent={updateStudent} notifications={notifications}/>}
        {role === 'teacher' && <TeacherPortal students={students} setStudents={setStudents}/>}
        {role === 'admin' && <AdminPortal broadcastAlert={msg => setNotifications(prev => [...prev, {id: Date.now(), message: msg}])}/>}
      </main>
    </div>
  );
}
